// Validate and stamp — pure relay, no intent gating
const raw = $input.first().json;
const body = raw.body || raw;

const MAX_DEPTH = 3;
const RATE_LIMIT_FILE = '/var/voicehub/audit/rate_limit.json';
const RATE_LIMIT_PER_DAY = 50;

// Required fields
if (!body || !body.payload || !body.payload.utterance) {
  return [{ json: { valid: false, reject_reason: 'Missing required field: payload.utterance' } }];
}

// Depth check
const depth = body.depth ?? 0;
if (depth > MAX_DEPTH - 1) {
  return [{ json: { valid: false, reject_reason: `Depth ${depth} exceeds maximum (${MAX_DEPTH - 1})` } }];
}

// Rate limiting
const fs = require('fs');
const auditDir = '/var/voicehub/audit';
if (!fs.existsSync(auditDir)) {
  fs.mkdirSync(auditDir, { recursive: true });
}
const today = new Date().toISOString().slice(0, 10);
let rateData = { date: today, count: 0 };
try {
  const r = fs.readFileSync(RATE_LIMIT_FILE, 'utf8');
  rateData = JSON.parse(r);
  if (rateData.date !== today) rateData = { date: today, count: 0 };
} catch (e) {}

if (rateData.count >= RATE_LIMIT_PER_DAY) {
  return [{ json: { valid: false, reject_reason: `Daily rate limit reached (${RATE_LIMIT_PER_DAY}/day)` } }];
}

rateData.count++;
fs.writeFileSync(RATE_LIMIT_FILE, JSON.stringify(rateData));

// Single UUID for both message_id and job_id
const crypto = require('crypto');
const messageId = crypto.randomUUID();

return [{
  json: {
    valid: true,
    payload: body.payload,
    source_agent: body.source_agent || 'voice',
    idempotency_key: body.idempotency_key || null,
    depth: depth,
    parent_message_id: body.parent_message_id || null,
    message_id: messageId,
    created_at: new Date().toISOString()
  }
}];

// Write mailbox file — single inbox, always to notification-agent
const fs = require('fs');
const item = $input.first().json;

const inboxDir = '/var/voicehub/mailboxes/inbox';
if (!fs.existsSync(inboxDir)) {
  fs.mkdirSync(inboxDir, { recursive: true });
}

// Filename: ISO timestamp (file-safe) + message_id
const ts = item.created_at.replace(/:/g, '-').replace(/\./g, '-');
const filename = `${ts}_${item.message_id}.md`;
const filepath = `${inboxDir}/${filename}`;

// Build frontmatter + body
let frontmatter = `---\nmessage_id: ${item.message_id}\nparent_message_id: ${item.parent_message_id || 'null'}\nfrom: voice\nto: notification-agent\nhop: 1\ncreated_at: ${item.created_at}`;
if (item.idempotency_key) {
  frontmatter += `\nidempotency_key: ${item.idempotency_key}`;
}
frontmatter += '\n---';

const context = item.payload.context ? JSON.stringify(item.payload.context) : 'none';
const content = `${frontmatter}\n\n**Utterance:** ${item.payload.utterance}\n**Context:** ${context}\n`;

fs.writeFileSync(filepath, content);

return [{ json: { ...item, mailbox_file: filepath } }];

// Append audit log entry
const fs = require('fs');
const item = $input.first().json;

const auditDir = '/var/voicehub/audit';
if (!fs.existsSync(auditDir)) {
  fs.mkdirSync(auditDir, { recursive: true });
}

const entry = {
  timestamp: item.created_at,
  message_id: item.message_id,
  payload_summary: item.payload.utterance.slice(0, 100),
  source_agent: item.source_agent,
  hop: 1,
  target: 'notification-agent',
  result: 'delivered'
};

fs.appendFileSync(
  `${auditDir}/escalations.jsonl`,
  JSON.stringify(entry) + '\n'
);

return [{ json: item }];

// Log rejection
const fs = require('fs');
const item = $input.first().json;

const auditDir = '/var/voicehub/audit';
if (!fs.existsSync(auditDir)) {
  fs.mkdirSync(auditDir, { recursive: true });
}

const entry = {
  timestamp: new Date().toISOString(),
  message_id: null,
  intent_type: 'unknown',
  payload_summary: item.reject_reason,
  source_agent: 'voice',
  depth: null,
  hop: null,
  target: null,
  result: 'rejected',
  reason: item.reject_reason
};

fs.appendFileSync(
  `${auditDir}/escalations.jsonl`,
  JSON.stringify(entry) + '\n'
);

return [{ json: item }];
